        // _excluded array is at slot 7
        bytes32 arraySlot = bytes32(uint256(7));
        bytes32 lengthSlot = keccak256(abi.encode(arraySlot));

        // Get current length
        uint256 currentLength = uint256(vm.load(TARGET, lengthSlot));
        console.log("Current _excluded array length:", currentLength);

        // Add a new address to the array
        address maliciousAddr = address(0x444);
        bytes32 elementSlot = bytes32(uint256(keccak256(abi.encode(arraySlot))) + currentLength);
        vm.store(TARGET, elementSlot, bytes32(uint256(uint160(maliciousAddr))));

        // Increment array length
        vm.store(TARGET, lengthSlot, bytes32(currentLength + 1));

        // Verify the address is in array
        uint256 newLength = uint256(vm.load(TARGET, lengthSlot));
        console.log("New _excluded array length:", newLength);
        address lastAddr = address(uint160(uint256(vm.load(TARGET, bytes32(uint256(keccak256(abi.encode(arraySlot))) + newLength - 1)))));
        console.log("Last address in _excluded:", lastAddr);

