        // The oracle condition: _excludedAddressToId[_excluded[lastIndex]] == 0
        // lastIndex = newLength - 1
        // _excluded[lastIndex] = maliciousAddr
        // _excludedAddressToId[maliciousAddr] = 0 (default)
        assertEq(mappingValue, 0, "Mapping value should be 0");

        // Also need to set _isExcluded[maliciousAddr] = true for consistency
        // _isExcluded is at slot 6
        bytes32 isExcludedSlot = bytes32(uint256(6));
        bytes32 isExcludedKey = bytes32(uint256(uint160(maliciousAddr)));
        bytes32 isExcludedValueSlot = keccak256(abi.encode(isExcludedKey, isExcludedSlot));
        vm.store(TARGET, isExcludedValueSlot, bytes32(uint256(1)));

        // Verify _isExcluded is set
        uint256 isExcludedValue = uint256(vm.load(TARGET, isExcludedValueSlot));
        console.log("_isExcluded[maliciousAddr]:", isExcludedValue);
        assertEq(isExcludedValue, 1, "Address should be marked as excluded");
    }

    // Helper function to read array length from storage
    function getExcludedLength(address tokenAddr) public view returns (uint256) {
        bytes32 slot = bytes32(EXCLUDED_ARRAY_SLOT);
        bytes32 lengthSlot = keccak256(abi.encode(slot));
        return uint256(vm.load(tokenAddr, lengthSlot));
    }

    // Helper function to read array element
    function getExcludedAt(address tokenAddr, uint256 index) public view returns (address) {
        bytes32 slot = bytes32(EXCLUDED_ARRAY_SLOT);
        bytes32 dataSlot = bytes32(uint256(keccak256(abi.encode(slot))) + index);
        return address(uint160(uint256(vm.load(tokenAddr, dataSlot))));
    }

    // Helper function to read mapping value
    function getExcludedAddressToId(address tokenAddr, address account) public view returns (uint256) {
        bytes32 slot = bytes32(EXCLUDED_MAPPING_SLOT);
        bytes32 key = bytes32(uint256(uint160(account)));
        bytes32 valueSlot = keccak256(abi.encode(key, slot));
        return uint256(vm.load(tokenAddr, valueSlot));
    }

    // Receive function if needed
    receive() external payable {}
}

